		/** 
		 * Tests creating a new Lead.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Lead");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Lead" );

			try {            
				Lead entity = LeadService.getLeadInstance().createLead( generateNewEntity() );
				thePrimaryKey = entity.getLeadId();
				LOGGER.info( "-- Successfully created a Lead with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Lead. 
		 */
		public Lead testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Lead" );

			Lead entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Lead with primary key" );
			msg.append( thePrimaryKey );
			
			LeadFetchOneSummary fetchOneSummary = new LeadFetchOneSummary( thePrimaryKey );

			try {
				entity = LeadService.getLeadInstance().getLead( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Lead " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Lead.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Lead." );

			StringBuilder msg = new StringBuilder( "Failed to update a Lead : " );        
			Lead entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Lead." );

				// for use later on...
				thePrimaryKey = entity.getLeadId();

				LeadService proxy = LeadService.getLeadInstance();            
				proxy.updateLead( entity );   

				LOGGER.info( "-- Successfully saved Lead - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Lead.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Lead." );

			try{
			    Lead entity = testRead(); 
				LeadService.getLeadInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Lead with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Lead with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Leads.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Leads:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Lead : " );        
			List<Lead> collection  = null;

			try {
				// call the static get method on the LeadService
				collection = LeadService.getLeadInstance().getAllLead();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Lead entity = null;            
					Iterator<Lead> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getLeadId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

